/* Deterministic meal calculation: no image API and no guessed portion sizes. */
const ingredientDialog=document.createElement('dialog');ingredientDialog.id='ingredientDialog';document.body.append(ingredientDialog);let ingredientDraft=null;
const mealNutrients=['calories','protein','carbs','fat'];
function ingredientTotals(items){const out={grams:0,calories:0,protein:0,carbs:0,fat:0};for(const x of items){if(!x.name||!Number.isFinite(x.grams)||x.grams<=0||x.grams>5000||mealNutrients.some(k=>!Number.isFinite(x.per100[k])||x.per100[k]<0))throw Error('راجع اسم ووزن وقيم كل مكوّن.');out.grams+=x.grams;for(const k of mealNutrients)out[k]+=x.per100[k]*x.grams/100}return Object.fromEntries(Object.entries(out).map(([k,v])=>[k,Math.round(v*10)/10]))}
function ingredientOptions(search=''){return Object.entries(foods).filter(([,f])=>f[0].toLowerCase().includes(search.toLowerCase())).map(([k,f])=>`<option value="${k}">${esc(f[0])}</option>`).join('')}
function openIngredientMeal(record=null,repeat=false,date=selected){ingredientDraft={profile:activeProfile,account:accountScope,id:repeat?null:record?.id,original:record?JSON.stringify(record):null,items:structuredClone(record?.componentFoods||[])};ingredientDialog.innerHTML=`<form id="ingredientForm"><div class="dialog-head"><h2>وجبة بالمكونات</h2><button type="button" class="icon-button" data-ingredient-close aria-label="إغلاق">×</button></div><p class="sub">اختر المكوّن والوزن. السعرات والماكروز تُحسب مباشرة دون خدمة تحليل الصور.</p><div class="form-grid">${input('componentDate','التاريخ الفعلي',repeat?date:record?.date||date,'date',true)}${select('componentMeal','الوجبة',['فطور','غداء','عشاء','سناك','قبل التمرين','بعد التمرين'],record?.name||'فطور')}${input('componentTime','الوقت',repeat?timeNow():record?.time||timeNow(),'time')}</div><details class="ingredient-presets"><summary>استخدام وجبة محفوظة</summary><select id="mealTemplateChoice" aria-label="وجباتي المحفوظة"><option value="">اختر وجبة</option>${(data.nutrition.mealTemplates||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('')}</select><button type="button" class="button secondary" data-ingredient-template>تحميل مكوناتها</button></details><div class="ingredient-add"><h3>إضافة طعام</h3><label class="field">بحث في الأطعمة<input id="ingredientSearch" type="search" placeholder="بيض، أرز، دجاج…"></label><div class="form-grid"><label class="field">الطعام<select id="ingredientFood">${ingredientOptions()}</select></label><label class="field">الوزن بالغرام<input id="ingredientGrams" type="number" min="0.1" max="5000" step="0.1" value="100"></label></div><button type="button" class="button secondary" data-ingredient-add>إضافة المكوّن</button><p class="sub">استخدم الوزن المأكول وطريقة التحضير المكتوبة. أضف الزيت منفصلًا. القيم العامة تختلف عن منتجك؛ استخدم ملصق العبوة عند توفره.</p><details><summary>طعام غير موجود؟ أدخل بيانات العبوة</summary><div class="form-grid"><label class="field">اسم الطعام<input id="customFoodName" maxlength="100"></label>${mealNutrients.map((k,i)=>`<label class="field">${['سعرات','بروتين غ','كارب غ','دهون غ'][i]} لكل ١٠٠ غ<input id="custom-${k}" type="number" min="0" max="${i===0?1000:100}" step="0.1"></label>`).join('')}<label class="field">الكمية المأكولة بالغرام<input id="customFoodGrams" type="number" min="0.1" max="5000" step="0.1" value="100"></label></div><button type="button" class="button secondary" data-ingredient-custom>إضافة من الملصق</button></details></div><div id="ingredientRows"></div><div id="ingredientSummary" class="ingredient-summary" role="status" aria-live="polite"></div><label class="field">اسم لحفظ هذه التركيبة وتكرارها (اختياري)<input id="ingredientTemplateTitle" maxlength="80" placeholder="مثلًا: فطور البيض والتوست"></label><p id="ingredientError" class="danger" role="alert"></p><div class="dialog-actions"><button class="button" type="submit">${ingredientDraft.id?'حفظ التعديلات':'حفظ الوجبة في السجل'}</button><button class="button secondary" type="button" data-ingredient-close>إلغاء</button></div><p class="sub">الأرقام محسوبة من الكميات والقيم المرجعية التي تختارها؛ ليست تحليلًا للصورة. المكونات تُحفظ مع الوجبة لتعديلها وإعادة حسابها.</p></form>`;renderIngredientRows();ingredientDialog.showModal();$('#ingredientForm').onsubmit=saveIngredientMeal}
function renderIngredientRows(){$('#ingredientRows').innerHTML=ingredientDraft.items.map((x,i)=>`<article class="ingredient-row"><div><b>${esc(x.name)}</b><small>${x.source==='label'?'من بيانات العبوة التي أدخلتها':'قيمة عامة من مكتبة الأطعمة'}</small></div><label>غرام<input type="number" value="${x.grams}" min="0.1" max="5000" step="0.1" data-ingredient-weight="${i}" aria-label="وزن ${esc(x.name)}"></label><button type="button" class="text-button danger" data-ingredient-remove="${i}" aria-label="حذف ${esc(x.name)}">حذف</button></article>`).join('')||'<p class="empty">أضف أول مكوّن لوجبتك.</p>';renderIngredientTotals()}
function renderIngredientTotals(){try{const t=ingredientTotals(ingredientDraft.items);$('#ingredientSummary').innerHTML=`<strong>${fmt(t.calories)} سعرة</strong><span>بروتين ${fmt(t.protein)} غ</span><span>كارب ${fmt(t.carbs)} غ</span><span>دهون ${fmt(t.fat)} غ</span><span>الوزن ${fmt(t.grams)} غ</span>`;$('#ingredientError').textContent=''}catch(e){$('#ingredientSummary').textContent='أكمل الكميات لحساب الإجمالي.';$('#ingredientError').textContent=e.message}}
function saveIngredientMeal(e){e.preventDefault();try{if(activeProfile!==ingredientDraft.profile||accountScope!==ingredientDraft.account)throw Error('تغير المستخدم؛ أعد فتح الوجبة في الملف المطلوب.');if(!ingredientDraft.items.length)throw Error('أضف مكونًا واحدًا على الأقل.');const next=structuredClone(data),old=ingredientDraft.id?next.meals.find(x=>x.id===ingredientDraft.id):null;if(ingredientDraft.id&&JSON.stringify(old)!==ingredientDraft.original)throw Error('تغيرت الوجبة على جهاز آخر؛ أغلق النافذة وافتحها من جديد.');const f=new FormData(e.target),date=f.get('componentDate');if(!dateValid(date))throw Error('اختر تاريخًا صحيحًا.');const total=ingredientTotals(ingredientDraft.items),record={...(old||{}),id:ingredientDraft.id||uid(),date,name:f.get('componentMeal'),time:f.get('componentTime'),food:ingredientDraft.items.map(x=>`${x.name} (${x.grams} غ)`).join('، ').slice(0,500),...total,estimated:false,calculationMethod:'ingredients',componentFoods:structuredClone(ingredientDraft.items)};const title=$('#ingredientTemplateTitle').value.trim();if(title){const list=next.nutrition.mealTemplates||[],existing=list.find(x=>x.title===title);if(!existing&&list.length>=30)throw Error('لديك ٣٠ تركيبة محفوظة؛ اترك الاسم فارغًا أو استخدم اسم تركيبة لتحديثها.');const template={id:existing?.id||uid(),title,items:structuredClone(ingredientDraft.items)};next.nutrition.mealTemplates=[...list.filter(x=>x.id!==template.id),template]}if(old)next.meals[next.meals.findIndex(x=>x.id===old.id)]=record;else next.meals.push(record);validate(next);if(commit(next,'تم حفظ الوجبة ومكوناتها')){selected=date;ingredientDialog.close();render()}}catch(err){$('#ingredientError').textContent=err.message}}
document.addEventListener('input',e=>{if(e.target.id==='ingredientSearch')$('#ingredientFood').innerHTML=ingredientOptions(e.target.value);if(e.target.hasAttribute('data-ingredient-weight')){ingredientDraft.items[Number(e.target.dataset.ingredientWeight)].grams=Number(e.target.value);renderIngredientTotals()}});
document.addEventListener('click',e=>{if(e.target.closest('[data-ingredients-open]')){const date=typeof mealPhotoDate==='string'&&mealPhotoDialog.open?mealPhotoDate:selected;if(mealPhotoDialog.open)closeMealPhoto();openIngredientMeal(null,false,date);return}if(e.target.closest('[data-ingredient-close]'))ingredientDialog.close();try{if(e.target.closest('[data-ingredient-add]')){const f=foods[$('#ingredientFood').value];if(!f)throw Error('اختر طعامًا من القائمة أو أدخل بيانات العبوة.');if(ingredientDraft.items.length>=30)throw Error('الحد الأقصى ٣٠ مكونًا.');const x={name:f[0],grams:Number($('#ingredientGrams').value),per100:Object.fromEntries(mealNutrients.map((k,i)=>[k,f[i+1]])),source:'library'};ingredientTotals([x]);ingredientDraft.items.push(x);renderIngredientRows()}if(e.target.closest('[data-ingredient-custom]')){if(ingredientDraft.items.length>=30)throw Error('الحد الأقصى ٣٠ مكونًا.');const values=mealNutrients.map(k=>$('#custom-'+k).value);if(values.some(x=>x===''))throw Error('أدخل القيم الأربع لكل ١٠٠ غ، بما فيها الصفر.');const x={name:$('#customFoodName').value.trim(),grams:Number($('#customFoodGrams').value),per100:Object.fromEntries(mealNutrients.map((k,i)=>[k,Number(values[i])])),source:'label'};if(x.per100.calories>1000||mealNutrients.slice(1).some(k=>x.per100[k]>100))throw Error('راجع القيم لكل ١٠٠ غ.');ingredientTotals([x]);ingredientDraft.items.push(x);renderIngredientRows()}const remove=e.target.closest('[data-ingredient-remove]');if(remove){ingredientDraft.items.splice(Number(remove.dataset.ingredientRemove),1);renderIngredientRows()}if(e.target.closest('[data-ingredient-template]')){const t=(data.nutrition.mealTemplates||[]).find(x=>x.id===$('#mealTemplateChoice').value);if(!t)throw Error('اختر وجبة محفوظة.');if(ingredientDraft.items.length&&!confirm('استبدال المكونات الحالية بالوجبة المحفوظة؟'))return;ingredientDraft.items=structuredClone(t.items);renderIngredientRows()}}catch(err){if(ingredientDialog.open)$('#ingredientError').textContent=err.message}});
const formBeforeIngredients=openForm;openForm=function(kind,record=null,repeat=false){if(kind==='meal'&&record?.componentFoods?.length)return openIngredientMeal(record,repeat);formBeforeIngredients(kind,record,repeat);if(kind==='meal'&&!record)$('#fields').insertAdjacentHTML('afterbegin','<div class="field full"><button type="button" class="button secondary" id="switchToIngredients">حساب تلقائي باختيار المكونات</button></div>');document.getElementById('switchToIngredients')?.addEventListener('click',()=>{$('#editor').close();openIngredientMeal()})};
